test({ sr: 'korisnik prepisuje podrazumevano', en: 'the user overwrites the default' }, () => {
  expect(mergeSettings({ theme: 'light', size: 12 }, { size: 14 })).toEqual({ theme: 'light', size: 14 });
});
test({ sr: 'novi ključ se dodaje', en: 'a new key is added' }, () => {
  expect(mergeSettings({ theme: 'light' }, { lang: 'sr' })).toEqual({ theme: 'light', lang: 'sr' });
});
test({ sr: 'false i 0 takođe prepisuju', en: 'false and 0 overwrite too' }, () => {
  expect(mergeSettings({ sound: true, volume: 5 }, { sound: false, volume: 0 })).toEqual({ sound: false, volume: 0 });
});

hiddenTests:
test('an empty user gives a copy of the defaults, not the same object', () => {
  const defaults = { a: 1 };
  const result = mergeSettings(defaults, {});
  expect(result).toEqual({ a: 1 });
  expect(result).not.toBe(defaults);
});
test('an empty text overwrites too', () => {
  expect(mergeSettings({ name: 'Ana' }, { name: '' })).toEqual({ name: '' });
});
test('both empty gives an empty object', () => {
  expect(mergeSettings({}, {})).toEqual({});
});
test('does not change defaults', () => {
  const defaults = { theme: 'light', size: 12 };
  mergeSettings(defaults, { size: 14, lang: 'sr' });
  expect(defaults).toEqual({ theme: 'light', size: 12 });
});
test('does not change user', () => {
  const user = { size: 14 };
  mergeSettings({ theme: 'light', size: 12 }, user);
  expect(user).toEqual({ size: 14 });
});
test('the defaults do not win over the user', () => {
  expect(mergeSettings({ x: 1, y: 2 }, { y: 5 })).toEqual({ x: 1, y: 5 });
});

solutions.code:
function mergeSettings(defaults, user) {
  return Object.assign({}, defaults, user);
}
